// intent: Verify that scan_string_run correctly skips quotes, backslashes, and control characters in long strings without failing.
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>
#include <iostream>

int main() {
    try {
        std::string s = "abcdefghijklmnopqrstuvwxyz0123456789\"\\\n\t";
        while (s.length() < 40) {
            s += "a";
        }
        nlohmann::json_document doc;
        doc.set(s);
        std::cout << "success with special chars, length: " << doc.dump().length() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "exception: " << e.what() << std::endl;
    }
    return 0;
}
